<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Ownership claims | Campus Finds</title><link rel="stylesheet" href="style.css"></head>
<body class="dashboard-body admin-dashboard-body"><div class="dashboard"><?php campus_admin_navigation('claims'); ?><main class="dashboard-main"><?php campus_admin_topbar($currentUser, $csrfToken); ?><div class="dashboard-content">
<div class="dashboard-heading"><div><p class="dashboard-eyebrow">Campus administration</p><h1>Ownership claims</h1><p class="dashboard-subtitle">Process private student proof of ownership and update claim decisions.</p></div></div>
<p class="admin-data-error" id="claims-error" role="alert" hidden></p><section class="admin-panel" aria-labelledby="claim-review-heading"><div class="admin-panel-heading"><div><h2 id="claim-review-heading">Student claim requests</h2><p>Move a claim to processing while verifying proof, then approve or reject it.</p></div><span class="admin-count-pill" id="claim-review-count">Loading…</span></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Item</th><th>Claimant</th><th>Student number / email</th><th>Private proof</th><th>Status</th><th>Process</th></tr></thead><tbody id="claim-review-rows"></tbody></table></div><div class="admin-empty-state" id="claim-review-empty" hidden><strong>No ownership claims yet</strong><p>Student claims on found items will appear here.</p></div></section>
<footer class="dashboard-footer"><span>Campus Finds · CvSU Cavite City Campus</span><span>Claim evidence is visible only to authorized School Admin.</span></footer></div></main></div>
<script>
const csrfToken=<?= json_encode($csrfToken) ?>,rows=document.querySelector('#claim-review-rows'),errorMessage=document.querySelector('#claims-error'),labels={pending:'Pending',processing:'Processing',approved:'Approved',rejected:'Rejected'};
function cell(row,value){const td=document.createElement('td');td.textContent=value||'—';row.append(td);return td} function button(label,className,action){const el=document.createElement('button');el.type='button';el.className=className;el.textContent=label;el.addEventListener('click',action);return el}
async function review(claimId,status){const endpoint=status==='processing'?'admin-claim-processing.php':'admin-claim-decision.php';const response=await fetch(endpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({claimId,status})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Claim review could not be saved.')}
async function loadClaims(){try{const response=await fetch('api.php?action=admin-claims',{credentials:'same-origin'}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not load ownership claims.');rows.replaceChildren();const claims=result.claims,pending=claims.filter(c=>c.status==='pending').length,processing=claims.filter(c=>c.status==='processing').length;document.querySelector('#claim-review-count').textContent=`${pending} pending · ${processing} processing`;document.querySelector('#claim-review-empty').hidden=claims.length>0;for(const claim of claims){const row=document.createElement('tr');cell(row,claim.item_title);cell(row,`${claim.first_name} ${claim.last_name}`);cell(row,`${claim.student_number||'—'}\n${claim.email}`);cell(row,claim.details);const status=cell(row,'');const badge=document.createElement('span');badge.className=`status-pill ${claim.status}`;badge.textContent=labels[claim.status]||claim.status;status.append(badge);const actions=document.createElement('td');if(claim.status==='pending'||claim.status==='processing'){actions.className='admin-review-actions';if(claim.status==='pending')actions.append(button('Processing','review-processing',async()=>{try{await review(claim.id,'processing');await loadClaims()}catch(e){showError(e)}}));actions.append(button('Approve','review-approve',async()=>{try{await review(claim.id,'approved');await loadClaims()}catch(e){showError(e)}}),button('Reject','review-reject',async()=>{try{await review(claim.id,'rejected');await loadClaims()}catch(e){showError(e)}}))}else actions.textContent='Reviewed';row.append(actions);rows.append(row)}}catch(e){showError(e)}}
function showError(e){errorMessage.textContent=e.message||'Claim action failed.';errorMessage.hidden=false}loadClaims();document.querySelector('[data-logout]').addEventListener('click',async event=>{const b=event.currentTarget;try{const r=await fetch('api.php?action=logout',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':b.dataset.csrf}});if(!r.ok)throw new Error();window.location.href='index.html'}catch(e){window.alert('Could not log out.')}});
</script></body></html>
